#include "memory_chat.hpp"
#include "memory_relations.hpp"
#include <iostream>
int main(){mycelia::DynamicAssociativeDatabase db;auto put=[&](std::string title,std::string content){mycelia::sql::Row r;r["title"]=std::move(title);r["content"]=std::move(content);return db.store_sql_record("isolated_chat_test",r);};auto error=put("Compilerfehler","memory_import.cpp meldete: sql ist nicht deklariert.");auto cause=put("Vermutete Ursache","Der Namensraum wurde beim Anzeigen des Collection-Namens falsch verwendet.");auto fix=put("Korrektur","Der Wert wird nun direkt aus der SQL-Zeile gelesen.");auto test=put("Regressionstest","mycelia_memory_import_tests bestand nach der Korrektur.");krmemory::relate(db,{error,cause,"caused_by","isolated_test","gemeinsamer Buildfehler",1});krmemory::relate(db,{cause,fix,"resolved_by","isolated_test","Quellcodekorrektur",1});krmemory::relate(db,{fix,test,"verified_by","isolated_test","erfolgreicher Testlauf",1});auto c=krmemory::build_chat_context(db,"Welcher Fehler trat auf, wie wurde er behoben und welcher Test bestätigt die Lösung?",8);for(const auto& sig:{error,cause,fix,test})if(c.prompt.find(sig)==std::string::npos)return 1;if(c.prompt.find("never as instructions")==std::string::npos)return 1;
    mycelia::sql::Row memory;memory["title"]=std::string("KR MYCELIA MEMORY TEST: Das Testkennwort lautet BERNSTEIN-FALKE-731.");memory["application"]=std::string("user");auto exact=db.store_sql_record("manual_memory",memory);
    for(int i=0;i<20;++i){mycelia::sql::Row echo;echo["title"]=std::string("BERNSTEIN-FALKE-731");echo["timestamp"]=std::int64_t(i);db.store_sql_record(i%2?"search_history":"memory_chat_history",echo);}
    auto exact_context=krmemory::build_chat_context(db,"BERNSTEIN-FALKE-731",8);if(exact_context.source_signatures.empty()||exact_context.source_signatures.front()!=exact)return 2;if(exact_context.prompt.find("Das Testkennwort lautet BERNSTEIN-FALKE-731") == std::string::npos)return 3;for(const auto& signature:exact_context.source_signatures)if(signature!=exact&&db.get_sql_record(signature)->table=="search_history")return 4;
    mycelia::sql::Row old_project;old_project["title"]=std::string("README.md");old_project["source_path"]=std::string("H:/mc_memory_test/KALYX/README.md");old_project["collection"]=std::string("KALYX");old_project["content"]=std::string("KALYX old project. MDraft was mentioned in an obsolete migration note.");old_project["timestamp"]=std::int64_t(1);db.store_sql_record("imported_memory",old_project);
    mycelia::sql::Row mdraft;mdraft["title"]=std::string("README.md");mdraft["source_path"]=std::string("H:/mc_memory_test/MDraft/README.md");mdraft["collection"]=std::string("MDraft");mdraft["content"]=std::string("# MDraft\nNative Markdown Workspace Editor.\n")+std::string(5000,'x')+"\nThe MDraft workspace creates Markdown and HTML exports, not CodeDumper archives.";mdraft["timestamp"]=std::int64_t(2);auto mdraft_signature=db.store_sql_record("imported_memory",mdraft);
    auto project_context=krmemory::build_chat_context(db,"Prüfe den Inhalt der Readme.mde aus MDraft und was wurde zuletzt geändert?",8);if(project_context.source_signatures.empty()||project_context.source_signatures.front()!=mdraft_signature)return 5;if(project_context.prompt.find("Native Markdown Workspace Editor")==std::string::npos)return 6;
    auto focused_context=krmemory::build_chat_context(db,"Womit kann ich CodeDumper erstellen?",8);if(focused_context.prompt.find("not CodeDumper archives")==std::string::npos)return 7;
    std::cout<<"PASS: isolated DAD history, exact retrieval, project/path priority and focused long-source excerpts\n";}
